use crate::{editor::{Action,Editor},pick_sources::{Part,Target},transform_draft::Kind};
use session_rust::Xform;
use std::rc::Rc;
fn editor()->Editor{let mut e=Editor::default();e.apply(Action::Close).unwrap();e}
fn command(e:&mut Editor,line:&str)->Result<(),String>{let action=if let Some(a)=e.tool_line(line){a.map_err(str::to_owned)?}else{let crate::commands::Command::Editor(a)=crate::commands::parse(line)? else{return Err("Editor command".into())};a};e.apply(action).map_err(|message|if message=="Shape input invalid"{e.tool_status.clone()}else{message.into()})?;Ok(())}
#[test]
fn copy_keeps_parent_name_colours_source_and_selection_with_new_identity_and_one_undo(){
    let mut e=editor();command(&mut e,"Box w0,0,0 1 2 3").unwrap();let id=e.scene.objects()[0].id;let original=e.scene.objects()[0].cad.as_ref().unwrap().source.clone();e.select_objects([id],false);std::rc::Rc::make_mut(&mut e.scene.view).faces.insert(id,[201,12,33]);let parent=e.scene.forest.documents[0].nodes.iter().find(|n|n.object==Some(id)).unwrap().parent;
    command(&mut e,"Copy 4,0,0").unwrap();let copy=e.scene.objects()[1].id;assert_ne!(e.scene.objects()[0].guid,e.scene.objects()[1].guid);assert!(Rc::ptr_eq(&e.scene.objects()[1].cad.as_ref().unwrap().source,&original));assert_eq!(e.selected_objects(),vec![id]);assert_eq!(e.scene.view.faces.get(&copy),Some(&[201,12,33]));let doc=&e.scene.forest.documents[0];let a=doc.nodes.iter().find(|n|n.object==Some(id)).unwrap();let b=doc.nodes.iter().find(|n|n.object==Some(copy)).unwrap();assert_eq!(a.label,b.label);assert_eq!(b.parent,parent);assert_eq!(e.scene.objects()[1].model.m[12],4.);
    let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut saved=crate::scene::Scene::empty();crate::scene_document::open(&mut saved,&bytes).unwrap();assert_eq!(saved.objects().len(),2);assert!(saved.objects().iter().any(|row|row.model.m[12]==4.));command(&mut e,"Undo").unwrap();assert_eq!(e.scene.objects().len(),1);command(&mut e,"Redo").unwrap();assert_eq!(e.scene.objects().len(),2);
}
#[test]
fn repeated_copy_targets_each_commit_once_and_enter_or_escape_keeps_originals_selected(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w1,0,0").unwrap();let id=e.scene.lines()[0].id;e.select_objects([id],false);command(&mut e,"Copy").unwrap();command(&mut e,"w0,0,0 w2,0,0 w4,0,0").unwrap();assert_eq!(e.scene.lines().len(),3);assert_eq!(e.draft.as_ref().unwrap().points,vec![[0.;3]]);assert_eq!(e.selected_objects(),vec![id]);command(&mut e,"").unwrap();assert!(e.draft.is_none());command(&mut e,"Undo").unwrap();assert_eq!(e.scene.lines().len(),2);command(&mut e,"Undo").unwrap();assert_eq!(e.scene.lines().len(),1);command(&mut e,"Redo").unwrap();command(&mut e,"Copy").unwrap();command(&mut e,"w0,0,0").unwrap();command(&mut e,"Escape").unwrap();command(&mut e,"Redo").unwrap();assert_eq!(e.scene.lines().len(),3);
}
#[test]
fn scaling_modes_reference_lengths_and_pending_preview_keep_original_source_unchanged(){
    let mut e=editor();command(&mut e,"Box w0,0,0 1 2 3").unwrap();let id=e.scene.objects()[0].id;let source=e.scene.objects()[0].cad.as_ref().unwrap().source.clone();e.select_objects([id],false);command(&mut e,"Scale").unwrap();command(&mut e,"1D w0,0,0").unwrap();assert!(command(&mut e,"2").is_err());assert_eq!(e.draft.as_ref().unwrap().points.len(),1);command(&mut e,"w1,0,0").unwrap();e.apply(Action::ToolHover(Some([2.,0.,0.]))).unwrap();assert_eq!(e.scene.objects()[0].model.m,Xform::identity().m);assert_eq!(e.display_scene().objects()[0].model.m[0],2.);command(&mut e,"3").unwrap();assert_eq!(e.scene.objects()[0].model.m[0],3.);assert_eq!(e.scene.objects()[0].model.m[5],1.);assert!(Rc::ptr_eq(&e.scene.objects()[0].cad.as_ref().unwrap().source,&source));command(&mut e,"Undo").unwrap();
    command(&mut e,"CPlane XZ").unwrap();command(&mut e,"Scale").unwrap();command(&mut e,"2D w0,0,0 2").unwrap();let model=&e.scene.objects()[0].model;assert_eq!([model.m[0],model.m[5],model.m[10]],[2.,1.,2.]);command(&mut e,"Undo").unwrap();command(&mut e,"Scale").unwrap();command(&mut e,"3D w0,0,0 w1,0,0 w2,0,0").unwrap();assert_eq!([e.scene.objects()[0].model.m[0],e.scene.objects()[0].model.m[5],e.scene.objects()[0].model.m[10]],[2.;3]);
}
#[test]
fn rotate_uses_gizmo_center_for_direct_axes_and_plane_normal_for_references(){
    let mut e=editor();command(&mut e,"Line w1,0,0 w2,0,0").unwrap();let id=e.scene.lines()[0].id;let source=e.scene.lines()[0].prepared.source.clone();e.select_objects([id],false);command(&mut e,"rot z 90").unwrap();let p=e.scene.lines()[0].model.transform_point(&source.start());assert!((p[0]-1.5).abs()<1e-12&&(p[1]+0.5).abs()<1e-12);assert!(Rc::ptr_eq(&e.scene.lines()[0].prepared.source,&source));command(&mut e,"Undo").unwrap();command(&mut e,"CPlane XZ").unwrap();command(&mut e,"Rotate").unwrap();command(&mut e,"w0,0,0 w1,0,0 w0,0,1").unwrap();let p=e.scene.lines()[0].model.transform_point(&source.start());assert!(p[0].abs()<1e-12&&(p[2]-1.).abs()<1e-12);
}
#[test]
fn invalid_transform_commands_batches_and_copy_parts_preserve_active_input_and_redo(){
    let mut e=editor();command(&mut e,"Curve w0,0,0 w1,1,0 w2,0,0").unwrap();let id=e.scene.paths()[0].id;e.select_objects([id],false);command(&mut e,"Copy 1,0,0").unwrap();command(&mut e,"Undo").unwrap();command(&mut e,"Scale").unwrap();command(&mut e,"w0,0,0").unwrap();for line in ["0","NaN","2 extra","Rotate q 90","Copy NaN,0,0"]{assert!(command(&mut e,line).is_err(),"{line}");assert_eq!(e.draft.as_ref().unwrap().tool.name(),"Scale");assert_eq!(e.draft.as_ref().unwrap().points.len(),1);assert_eq!(e.scene.paths().len(),1);}command(&mut e,"Escape").unwrap();command(&mut e,"Redo").unwrap();assert_eq!(e.scene.paths().len(),2);e.apply(Action::Controls(true)).unwrap();e.apply(Action::PickedTarget(Some(Target{owner:id,part:Part::Control(1)}))).unwrap();assert!(command(&mut e,"Copy").is_err());assert!(e.draft.is_none());
}
#[test]
fn typed_move_and_scale_edit_a_rational_curve_control_without_changing_its_weight(){
    let mut e=editor();command(&mut e,"Nurbs Curve Arc Center w0,0,0 1 90").unwrap();let id=e.scene.paths()[0].id;let crate::chain::Source::Curve(original,_)=e.scene.paths()[0].prepared.source.clone()else{panic!("Curve")};e.apply(Action::Controls(true)).unwrap();e.apply(Action::PickedTarget(Some(Target{owner:id,part:Part::Control(1)}))).unwrap();command(&mut e,"m 0.125,0.25,0").unwrap();let crate::chain::Source::Curve(edited,_)=&e.scene.paths()[0].prepared.source else{panic!("Curve")};assert_eq!(edited.get_cv_4d(1).unwrap().3,original.get_cv_4d(1).unwrap().3);assert_eq!(edited.m_nurbsknot,original.m_nurbsknot);let a=original.get_cv(1).unwrap();let b=edited.get_cv(1).unwrap();assert!((b[0]-a[0]-0.125).abs()<1e-12&&(b[1]-a[1]-0.25).abs()<1e-12);command(&mut e,"Undo").unwrap();e.apply(Action::PickedTarget(Some(Target{owner:id,part:Part::Control(1)}))).unwrap();command(&mut e,"Scale").unwrap();command(&mut e,"w0,0,0 2").unwrap();let crate::chain::Source::Curve(edited,_)=&e.scene.paths()[0].prepared.source else{panic!("Curve")};assert_eq!(edited.get_cv_4d(1).unwrap().3,original.get_cv_4d(1).unwrap().3);assert!((edited.get_cv(1).unwrap()[0]-2.*a[0]).abs()<1e-12);command(&mut e,"Undo").unwrap();let crate::chain::Source::Curve(restored,_)=&e.scene.paths()[0].prepared.source else{panic!("Curve")};assert!(Rc::ptr_eq(restored,&original));
}
#[test]
fn cad_face_edits_rebuild_original_boundary_geometry_and_undo_to_the_shared_source(){
    let mut e=editor();command(&mut e,"Box w0,0,0 1 2 3").unwrap();let id=e.scene.objects()[0].id;let original=e.scene.objects()[0].cad.as_ref().unwrap().source.clone();e.apply(Action::PickedTarget(Some(Target{owner:id,part:Part::Face(0)}))).unwrap();command(&mut e,"Move 0,0,0.125").unwrap();let next=&e.scene.objects()[0].cad.as_ref().unwrap().source;assert!(!Rc::ptr_eq(next,&original));assert_eq!(next.guid(),original.guid());assert!(next.is_valid()&&next.is_closed(0));assert_eq!(e.scene.objects()[0].model.m,Xform::identity().m);command(&mut e,"Undo").unwrap();assert!(Rc::ptr_eq(&e.scene.objects()[0].cad.as_ref().unwrap().source,&original));command(&mut e,"Redo").unwrap();assert!(!Rc::ptr_eq(&e.scene.objects()[0].cad.as_ref().unwrap().source,&original));let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut saved=crate::scene::Scene::empty();crate::scene_document::open(&mut saved,&bytes).unwrap();assert_eq!(saved.objects()[0].cad.as_ref().unwrap().source.to_proto(),e.scene.objects()[0].cad.as_ref().unwrap().source.to_proto());
}
#[test]
fn cancelling_a_transform_releases_temporary_owners_and_keeps_placement_and_history(){
    let mut e=editor();command(&mut e,"Box w0,0,0 1 1 1").unwrap();let id=e.scene.objects()[0].id;e.select_objects([id],false);e.apply(Action::BeginTransformation(Kind::Rotate)).unwrap();command(&mut e,"w0,0,0 w1,0,0").unwrap();e.apply(Action::ToolHover(Some([0.,1.,0.]))).unwrap();assert_ne!(e.display_scene().objects()[0].model.m,e.scene.objects()[0].model.m);command(&mut e,"Escape").unwrap();assert!(e.transform_preview.is_none());assert_eq!(e.scene.objects()[0].model.m,Xform::identity().m);command(&mut e,"Undo").unwrap();assert!(e.scene.objects().is_empty());
}
#[test]
fn copy_under_duplicate_named_nested_groups_preserves_local_save_placement_and_other_source_holders(){
    use prost::Message;
    let mut original=session_rust::Session::new("placed");original.add_group("parts");let group=original.add_group("parts");original.set_xform(&group.borrow().name,Xform::translation(10.,0.,0.));let node=original.add_line(session_rust::Line::new(0.,0.,0.,1.,0.,0.),Some(&group));let guid=node.borrow().name.clone();let source=original.to_proto();let bytes=source.encode_to_vec();let mut e=editor();crate::scene_document::import(&mut e.scene,&bytes,"placed",&Xform::translation(100.,0.,0.),0.).unwrap();let id=e.scene.lines()[0].id;e.select_objects([id],false);command(&mut e,"Copy 0,5,0").unwrap();assert_eq!(e.scene.lines()[1].model.m[12],110.);assert_eq!(e.scene.lines()[1].model.m[13],5.);let doc=&e.scene.forest.documents[0];let a=doc.nodes.iter().find(|node|node.object==Some(id)).unwrap();let b=doc.nodes.iter().find(|node|node.object==Some(e.scene.lines()[1].id)).unwrap();assert_eq!(a.parent,b.parent);assert!(Rc::ptr_eq(&e.scene.lines()[0].prepared.source,&e.scene.lines()[1].prepared.source));assert_eq!(original.to_proto(),source);assert!(original.lookup.contains_key(&guid));let archive=crate::scene_archive::save(&e.scene).unwrap();let mut saved=crate::scene::Scene::empty();crate::scene_document::open(&mut saved,&archive).unwrap();assert_eq!(saved.lines().len(),2);assert!(saved.lines().iter().any(|row|row.model.m[12]==110.&&row.model.m[13]==5.));
}
